mapper.select:
SELECT i.*, m.code AS material_code, m.name AS material_name, m.spec, s.name AS supplier_name, o.wo_no, u.nickname AS create_by_name, p.name AS plan_name, op.name AS op_name FROM mes_inspection i JOIN wms_material m ON m.id = i.material_id LEFT JOIN scm_supplier s ON s.id = i.supplier_id LEFT JOIN mes_work_order o ON o.id = i.wo_id LEFT JOIN sys_user u ON u.id = i.create_by LEFT JOIN qms_inspection_plan p ON p.id = i.plan_id LEFT JOIN mes_wo_op op ON op.id = i.wo_op_id
i.type = #{q.type} AND i.result = #{q.result} AND i.supplier_id = #{q.supplierId}
AND (i.insp_no LIKE CONCAT('%', #{q.keyword}, '%') OR i.source_no LIKE CONCAT('%', #{q.keyword}, '%') OR m.code LIKE CONCAT('%', #{q.keyword}, '%') OR m.name LIKE CONCAT('%', #{q.keyword}, '%'))
AND i.inspect_date >= #{q.beginDate} AND i.inspect_date <= #{q.endDate}
ORDER BY i.id DESC

SELECT supplier_id AS "supplierId", COUNT(*) AS "batches",
       SUM(CASE WHEN result <> 'FAIL' THEN 1 ELSE 0 END) AS "passBatches"
FROM mes_inspection
WHERE type = 'IQC' AND status = 'CONFIRMED'
  AND supplier_id IN #{id}
  AND inspect_date >= #{beginDate}
  AND inspect_date <= #{endDate}
GROUP BY supplier_id

SELECT COALESCE(SUM(inspect_qty), 0)
FROM mes_inspection
WHERE type = 'FQC' AND status = 'CONFIRMED' AND result <> 'FAIL' AND wo_id = #{woId}
